using System.Globalization;
using System.Text;
using System.Text.Json;
using ZePractice;
using CounterStrikeSharp.API.Modules.Cvars;

var tests = new List<object>();
void Check(bool value, string message = "assertion failed") { if (!value) throw new Exception(message); }
void Test(string name, Action action) { try { action(); tests.Add(new { name, passed=true }); Console.WriteLine("PASS " + name); } catch(Exception ex) { tests.Add(new { name, passed=false, error=ex.Message }); Console.WriteLine("FAIL " + name + ": " + ex); } }
void Throws(Action action) { bool thrown=false; try { action(); } catch { thrown=true; } Check(thrown, "expected rejection"); }
var corpus = args.Length > 0 ? args[0] : @"E:\mapper\chana\临时文件夹\ze-practice-build-20261011\upstream\cs2-master";
var fixtures = @"E:\mapper\chana\临时文件夹\ze-practice-build-20261011\map-config-test-fixtures\" + Guid.NewGuid().ToString("N");
Directory.CreateDirectory(Path.Combine(fixtures,"2001","csgo","cfg","map-configs"));
string CfgPath(string map) => FysConfigReader.ResolveMapFile(fixtures,"2001","csgo/cfg/map-configs",map,".cfg");
void WriteCfg(string map,string text) => File.WriteAllText(CfgPath(map),text,new UTF8Encoding(false));
void Seed()
{
    ConVar.Vars.Clear(); ConVar.Writes.Clear(); ConVar.ClampName=null;
    foreach(var name in FysConfigReader.Specifications.Values.SelectMany(x=>x.Targets).Concat(new[]{"zr_enable","mp_solid_teammates","cs2f_infinite_reserve_ammo","mp_ignore_round_win_conditions","mp_limitteams","mp_autoteambalance","mp_maxrounds","mp_freezetime","mp_warmuptime","mp_match_can_clinch","mp_match_end_restart","mp_match_end_changelevel","mp_respawn_on_death_ct","mp_respawn_on_death_t"}).Distinct()) ConVar.Vars[name]=new(name,"9");
}
ZePracticePlugin Plugin(string map="ze_test", bool practice=false) => new(){FysDirectory=fixtures,CurrentMapKey=map,IsPractice=practice};

Test("map knives allowed by default",()=>{var options=new PublicGameplayOptions();options.Validate();Check(options.AllowZombieMapKnives);});
Test("legacy config inherits map knife allowance",()=>Check(JsonSerializer.Deserialize<ZePracticeConfig>("{\"PublicGameplay\":{}}")!.PublicGameplay.AllowZombieMapKnives));
Test("explicit strict knife policy preserved",()=>Check(!JsonSerializer.Deserialize<PublicGameplayOptions>("{\"AllowZombieMapKnives\":false}")!.AllowZombieMapKnives));

Test("31 explicit specifications / coverage classes",()=>{Check(FysConfigReader.Specifications.Count==31);Check(FysConfigReader.Specifications.Values.Count(x=>x.Disposition==FysSettingDisposition.ConVar)==10);Check(FysConfigReader.Specifications.Values.Count(x=>x.Disposition==FysSettingDisposition.Managed)==10);Check(FysConfigReader.Specifications.Values.Count(x=>x.Disposition==FysSettingDisposition.Unsupported)==11);});
Test("CFG CRLF/BOM/comments/boolean/quoted",()=>{var r=FysConfigReader.ParseCfg("\uFEFF//comment\r\n\tmp_timelimit \"45.0\" // after\r\nze_infect_teleport_to_spawn false\r\n");Check(r.IsValid);Check(r.Values.Count==2);Check(r.Values["mp_timelimit"]==45);Check(r.Values["ze_infect_teleport_to_spawn"]==0);});
Test("duplicate last value and explicit diagnostic",()=>{var r=FysConfigReader.ParseCfg("mp_timelimit 20\nmp_timelimit 40");Check(r.IsValid&&r.Values["mp_timelimit"]==40);Check(r.Diagnostics.Any(x=>x.Code=="duplicate"));});
Test("metadata echo/say are data only",()=>{var r=FysConfigReader.ParseCfg("Echo Executed config for ze_test.\nSay \"地图测试 // 不是注释\"");Check(r.IsValid&&r.MetadataMessages.Count==2&&r.Values.Count==0);});
Test("reject arbitrary console commands",()=>{var r=FysConfigReader.ParseCfg("exec autoexec.cfg\nrcon_password pwn\nsv_cheats 1\nquit");Check(r.IsValid&&r.Values.Count==0);Check(r.Diagnostics.Count(x=>x.Code=="unmapped")==4);});
Test("reject command separator",()=>{var r=FysConfigReader.ParseCfg("mp_timelimit 30; quit");Check(!r.IsValid);Check(r.Values.Count==0);});
Test("reject multiline quoted/control chars",()=>{Check(!FysConfigReader.ParseCfg("mp_timelimit \"30\nquit\"").IsValid);Check(!FysConfigReader.ParseCfg("mp_timelimit 30\0").IsValid);});
Test("reject invalid range/nonfinite/integer type",()=>{foreach(var text in new[]{"mp_timelimit 0","mp_timelimit 71","mp_roundtime NaN","mp_roundtime Infinity","ze_infect_mother_ratio 1.5","ze_infect_teleport_to_spawn 2","sv_falldamage_scale -1"})Check(!FysConfigReader.ParseCfg(text).IsValid,text);});
Test("culture invariant numbers",()=>{var old=CultureInfo.CurrentCulture;try {CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("fr-FR");Check(FysConfigReader.ParseCfg("ze_knockback_scale 1.5").Values["ze_knockback_scale"]==1.5);Check(!FysConfigReader.ParseCfg("ze_knockback_scale 1,5").IsValid);}finally{CultureInfo.CurrentCulture=old;}});
Test("upstream minus-one purchase sentinel",()=>{var r=FysConfigReader.ParseCfg("ze_weapons_round_decoy -1");Check(r.IsValid&&r.Values["ze_weapons_round_decoy"]==-1);});
Test("JSONC comments/trailing comma/BOM",()=>{using var d=FysConfigReader.ParseJsonc("\uFEFF{ // c\n\"text\":\"门\\n打开\", }");Check(d.RootElement.GetProperty("text").GetString()=="门\n打开");});
Test("JSONC corruption/oversize",()=>{Throws(()=>FysConfigReader.ParseJsonc("{ broken"));Throws(()=>FysConfigReader.ParseJsonc(new string(' ', FysConfigReader.MaximumFileBytes+1)));Check(!FysConfigReader.ParseCfg(new string(' ',FysConfigReader.MaximumFileBytes+1)).IsValid);});
Test("normal map / Workshop basename",()=>{Check(FysConfigReader.NormalizeMapKey("workshop/123456/Ze_Test.vpk")=="ze_test");Check(FysConfigReader.NormalizeMapKey("ze_forhidden_slicoo_cn")=="ze_forhidden_slicoo_cn");});
Test("map traversal/control/drive/UNC rejected",()=>{foreach(var name in new[]{"../config","ze/other","ze\\other","C:\\test","\\\\host\\file","ze_test\nquit","workshop/../ze_test","workshop/123/../../file","ze..x"})Throws(()=>FysConfigReader.ResolveMapFile(fixtures,"2001","csgo/cfg/map-configs",name,".cfg"));});
Test("server/directory/extension traversal rejected",()=>{Throws(()=>FysConfigReader.ResolveMapFile(fixtures,"../2001","csgo/cfg/map-configs","ze_test",".cfg"));Throws(()=>FysConfigReader.ResolveMapFile(fixtures,"2001","../other","ze_test",".cfg"));Throws(()=>FysConfigReader.ResolveMapFile(fixtures,"2001","csgo/cfg/map-configs","ze_test",".cfg/../../x"));});
Test("valid resolved path stays beneath root",()=>Check(CfgPath("ze_test").StartsWith(fixtures+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)));
Test("map merge/template precedence and in-round game-cash mapping",()=>{Seed();WriteCfg("_template","mp_roundtime 25\nze_cash_damage_zombie 1.2");WriteCfg("ze_test","mp_roundtime 40\nze_knockback_scale 2");using var s=new MapConfigService(Plugin());s.OnMapStart("ze_test");Check(s.LastReport.Errors.Count==0);Check(ConVar.Find("mp_roundtime")!.StringValue=="40");Check(ConVar.Find("mp_roundtime_defuse")!.StringValue=="40");Check(s.GetFloat("ze_cash_damage_zombie")==1.2f);Check(ConVar.Find("zr_knockback_scale")!.StringValue=="10");Check(s.LastReport.DirectSettingCount==10);Check(s.LastReport.UnsupportedSettings.Count==11&&s.LastReport.DeferredSettings.Count==10);});
Test("per-map reset prevents previous-map leakage",()=>{Seed();WriteCfg("_template","mp_roundtime 25");WriteCfg("ze_first","ze_knockback_scale 2.2");WriteCfg("ze_next","mp_roundtime 35");var p=Plugin("ze_first");using var s=new MapConfigService(p);s.OnMapStart("ze_first");Check(s.GetFloat("ze_knockback_scale")==2.2f);p.CurrentMapKey="ze_next";s.OnMapStart("ze_next");Check(s.GetFloat("ze_knockback_scale")==1);Check(ConVar.Find("zr_knockback_scale")!.StringValue=="5");});
Test("invalid one file is atomic and defaults survive",()=>{Seed();WriteCfg("_template","mp_roundtime 25");WriteCfg("ze_bad","mp_roundtime 55\nze_knockback_scale NaN");using var s=new MapConfigService(Plugin("ze_bad"));s.ApplyCurrentMap();Check(s.GetFloat("mp_roundtime")==25);Check(s.LastReport.LoadedFiles.Count==1);Check(s.LastReport.Errors.Any(x=>x.Contains("entire CFG")));});
Test("invalid map path cannot read but mode overrides still apply",()=>{Seed();using var s=new MapConfigService(Plugin("../escape",true));s.ApplyCurrentMap();Check(s.LastReport.Errors.Any(x=>x.Contains("path rejected")));Check(ConVar.Find("zr_enable")!.StringValue=="0");Check(s.LastReport.PracticeOverridesApplied);});
Test("missing map logged plus defaults instead of crash",()=>{Seed();using var s=new MapConfigService(Plugin("ze_missing"));s.ApplyCurrentMap();Check(s.LastReport.Errors.Any(x=>x.Contains("No map CFG")));Check(s.GetFloat("ze_knockback_scale")==1);});
Test("managed settings require actual consumer",()=>{Seed();WriteCfg("ze_health","ze_spawn_start_health_override 150");using var s=new MapConfigService(Plugin("ze_health"));double received=0;s.RegisterManagedSettingHandler("ze_spawn_start_health_override",v=>received=v);s.ApplyCurrentMap();Check(received==150&&s.SpawnHealthOverride==150);Check(s.LastReport.AppliedManagedSettings.Contains("ze_spawn_start_health_override"));Check(!s.LastReport.DeferredSettings.ContainsKey("ze_spawn_start_health_override"));});
Test("failing consumer isolated",()=>{Seed();using var s=new MapConfigService(Plugin());s.RegisterManagedSettingHandler("ze_weapons_spawn_decoy",_=>throw new InvalidOperationException("test"));s.ApplyCurrentMap();Check(s.LastReport.Errors.Any(x=>x.Contains("consumer failed")));Check(s.LastReport.DirectSettingCount==10);});
Test("round-start preserves data but reasserts no-infection",()=>{Seed();var p=Plugin(practice:true);p.Config.EnableZombieMode=true;using var s=new MapConfigService(p);s.ApplyCurrentMap();ConVar.Find("zr_enable")!.StringValue="1";s.OnRoundStart();Check(ConVar.Find("zr_enable")!.StringValue=="0");Check(ConVar.Find("mp_ignore_round_win_conditions")!.StringValue=="1");Check(ConVar.Find("mp_timelimit")!.StringValue=="0");Check(s.LastReport.PracticeOverridesApplied);});
Test("practice off restores previous flags + enables configured ZE",()=>{Seed();var p=Plugin(practice:true);p.Config.EnableZombieMode=true;using var s=new MapConfigService(p);s.ApplyCurrentMap();p.IsPractice=false;s.ApplyCurrentMap();Check(ConVar.Find("zr_enable")!.StringValue=="1");Check(ConVar.Find("mp_ignore_round_win_conditions")!.StringValue=="9");Check(ConVar.Find("mp_timelimit")!.StringValue=="45");});
Test("disabled FYS adaptation still protects practice",()=>{Seed();var p=Plugin(practice:true);p.Config.ApplyFysMapParameters=false;using var s=new MapConfigService(p);s.ApplyCurrentMap();Check(s.LastReport.LoadedFiles.Count==0&&s.LastReport.DirectSettingCount==0);Check(ConVar.Find("zr_enable")!.StringValue=="0");});
Test("FYS knockback factor normal 1.0 preserves local CS2Fixes 5.0 baseline",()=>{Seed();using var s=new MapConfigService(Plugin("ze_missing_knockback"));s.ApplyCurrentMap();Check(s.GetFloat("ze_knockback_scale")==1);Check(ConVar.Find("zr_knockback_scale")!.StringValue=="5");});
Test("missing convar reports NOT applied",()=>{Seed();ConVar.Vars.Remove("zr_knockback_scale");using var s=new MapConfigService(Plugin());s.ApplyCurrentMap();Check(s.LastReport.Errors.Any(x=>x.Contains("NOT applied: zr_knockback_scale")));Check(s.LastReport.DirectSettingCount==9);});
Test("native clamp detected by readback",()=>{Seed();ConVar.ClampName="mp_roundtime";using var s=new MapConfigService(Plugin());s.ApplyCurrentMap();Check(s.LastReport.Errors.Any(x=>x.Contains("read back")));Check(s.LastReport.DirectSettingCount==9);});
Test("dispose restores owned values but respects later admin edits",()=>{Seed();var s=new MapConfigService(Plugin(practice:true));s.ApplyCurrentMap();ConVar.Find("mp_freezetime")!.StringValue="4";s.Dispose();Check(ConVar.Find("mp_ignore_round_win_conditions")!.StringValue=="9");Check(ConVar.Find("mp_freezetime")!.StringValue=="4");var before=ConVar.Writes.Count;s.OnRoundStart();s.Dispose();Check(ConVar.Writes.Count==before);});
Test("all direct setters write only finite scalar values",()=>{Seed();using var s=new MapConfigService(Plugin(practice:true));s.ApplyCurrentMap();Check(ConVar.Writes.All(x=>double.TryParse(x.Value,NumberStyles.Float,CultureInfo.InvariantCulture,out var v)&&double.IsFinite(v)));});
int files=0, lines=0; var unique=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var unmapped=new HashSet<string>();
Test("entire upstream 2001 CFG corpus parses",()=>{foreach(var path in Directory.EnumerateFiles(Path.Combine(corpus,"2001","csgo","cfg","map-configs"),"*.cfg")){var r=FysConfigReader.ParseCfg(FysConfigReader.ReadBoundedText(path));Check(r.IsValid,path+": "+string.Join("; ",r.Diagnostics.Where(x=>x.IsError)));files++;lines+=r.SettingLines;foreach(var key in r.Values.Keys)unique.Add(key);foreach(var d in r.Diagnostics.Where(x=>x.Code=="unmapped"))unmapped.Add(d.Message);}Check(files>=700&&unique.Count==31);Check(unmapped.Count==0);});
var summary=new {tests, corpus=new {files,settingLines=lines,uniqueSettings=unique.Count,unmappedCommands=unmapped},fixtures};
var json=JsonSerializer.Serialize(summary,new JsonSerializerOptions{WriteIndented=true});
File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"test-results.json"),json,new UTF8Encoding(false));
Console.WriteLine($"Corpus: {files} CFG files, {lines} setting lines, {unique.Count} setting names, {unmapped.Count} unmapped commands.");
Console.WriteLine("Results: "+Path.Combine(AppContext.BaseDirectory,"test-results.json"));
return tests.Any(x=>x.GetType().GetProperty("passed")!.GetValue(x) is false)?1:0;
